const fs=require('fs'),path=require('path');let timer,running=false,opened=false;
exports.load=()=>{timer=setInterval(async()=>{if(running)return;running=true;const project=Editor.Project.path;try{if(!opened){await Editor.Message.request('scene','execute-scene-script',{name:'p6-probe',method:'create',args:[project]});await Editor.Message.request('asset-db','refresh-asset','db://assets/RuntimeQualification.scene');const id=await Editor.Message.request('asset-db','query-uuid','db://assets/RuntimeQualification.scene');if(!id||!await Editor.Message.request('scene','query-is-ready'))return;await Editor.Message.request('scene','open-scene',id);const url=await Editor.Message.request('preview','query-preview-url');fs.writeFileSync(path.join(project,'p6-ready.json'),JSON.stringify({url}));opened=true;}
 const file=path.join(project,'p6-config-ready.json');if(fs.existsSync(file)){fs.unlinkSync(file);await Editor.Message.request('asset-db','refresh-asset','db://assets/resources/kit-preview-config.json');const url=await Editor.Message.request('preview','query-preview-url');fs.writeFileSync(path.join(project,'p6-browser-ready.json'),JSON.stringify({url}));}
 }catch(e){console.warn('[p6-probe] '+String(e.message||e));}finally{running=false;}},1000);};exports.unload=()=>clearInterval(timer);
